model.the_tuva_project.normalized_input_.raw_code:
{{ config(
     enabled = var('claims_preprocessing_enabled',var('claims_enabled',var('tuva_marts_enabled',False)))
 | as_bool
   )
}}

{% set procedure_cols = range(1, 26) %}

select
    claim_id
    , data_source
    {% for i in procedure_cols %}
    , max(case when column_name = 'procedure_code_{{ i }}' then procedure_code else null end) as procedure_code_{{ i }}
    {% endfor %}
    , cast('{{ var('tuva_last_run') }}' as {{ dbt.type_timestamp() }}) as tuva_last_run
from {{ ref('normalized_input__int_procedure_code_intermediate') }}
group by
    claim_id
    , data_source

{{ config(
     enabled = var('claims_preprocessing_enabled',var('claims_enabled',var('tuva_marts_enabled',False)))
 | as_bool
   )
}}


select
    claim_id
    , claim_line_number
    , data_source
    , pos.place_of_service_code as normalized_code
    , pos.place_of_service_description as normalized_description
    , cast('{{ var('tuva_last_run') }}' as {{ dbt.type_timestamp() }}) as tuva_last_run
from {{ ref('normalized_input__stg_medical_claim') }} as med
left outer join {{ ref('terminology__place_of_service') }} as pos
    {% if target.type == 'fabric' %}
        on RIGHT(REPLICATE('0', 2) + med.place_of_service_code, 2) = pos.place_of_service_code
    {% else %}
        on lpad(med.place_of_service_code, 2, '0') = pos.place_of_service_code
    {% endif %}
where claim_type = 'professional'

{{ config(
     enabled = var('claims_preprocessing_enabled',var('claims_enabled',var('tuva_marts_enabled',False)))
 | as_bool
   )
}}


select
    claim_id
    , claim_line_number
    , data_source
    , rev.revenue_center_code as normalized_code
    , rev.revenue_center_description as normalized_description
    , cast('{{ var('tuva_last_run') }}' as {{ dbt.type_timestamp() }}) as tuva_last_run
from {{ ref('normalized_input__stg_medical_claim') }} as med
left outer join {{ ref('terminology__revenue_center') }} as rev
    {% if target.type == 'fabric' %}
        on RIGHT(REPLICATE('0', 4) + med.revenue_center_code, 4) = rev.revenue_center_code
    {% else %}
        on lpad(med.revenue_center_code, 4, '0') = rev.revenue_center_code
    {% endif %}
where claim_type = 'institutional'

{{ config(
     enabled = var('claims_preprocessing_enabled', var('claims_enabled', var('tuva_marts_enabled', False)))
     | as_bool
   )
}}

{% set diagnosis_cols = range(1, 26) %}

select
    claim_id
    , data_source
    {% for i in diagnosis_cols %}
    , max(case when column_name = 'diagnosis_code_{{ i }}' then diagnosis_code else null end) as diagnosis_code_{{ i }}
    {% endfor %}
    , cast('{{ var('tuva_last_run') }}' as {{ dbt.type_timestamp() }}) as tuva_last_run
from {{ ref('normalized_input__int_diagnosis_code_intermediate') }}
group by
    claim_id
    , data_source

