macro.the_tuva_project.smart_union.macro_sql:
{% macro smart_union(relations, source_index='_source') %}
{#
    Unions relations with automatic alignment of columns.
    Missing columns are filled with NULL. Extension columns (prefixed) are sorted last.

    smart_union vs dbt_utils.union_relations:
    ┌─────────────────────┬─────────────────────────────────────┬─────────────────────────┐
    │ Feature             │ dbt_utils.union_relations           │ smart_union             │
    ├─────────────────────┼─────────────────────────────────────┼─────────────────────────┤
    │ Source tracking     │ Full path string                    │ Numeric index (1, 2...) │
    │ Filter syntax       │ WHERE _source LIKE '%table_name%'   │ WHERE _source = 1       │
    │ Column ordering     │ Arbitrary                           │ Core first, ext_ last   │
    └─────────────────────┴─────────────────────────────────────┴─────────────────────────┘

    Arguments:
        relations: List of relations to union
        source_index: Source tracking column name (default: '_source'). Set to none to disable.

    Usage:
        {{ smart_union([ref('stg_claims'), ref('stg_clinical')]) }}
        -- Adds _source column: 1 = first relation, 2 = second, etc.
        -- Filter with: WHERE _source = 1

        -- Without source tracking:
        {{ smart_union([ref('stg_claims'), ref('stg_clinical')], source_index=none) }}
#}

{%- if not execute -%}
    {{ return('') }}
{%- endif -%}

{%- set all_columns = {} -%}
{%- for relation in relations -%}
    {%- set cols = adapter.get_columns_in_relation(relation) -%}
    {%- for col in cols -%}
        {%- if col.name.lower() not in all_columns -%}
            {%- do all_columns.update({col.name.lower(): col}) -%}
        {%- endif -%}
    {%- endfor -%}
{%- endfor -%}

{#- Get passthrough prefix for column detection -#}
{%- set passthrough_config = var('passthrough', {}) -%}
{%- set passthrough_prefix = passthrough_config.get('prefix', 'x_').lower() -%}

{%- set core_cols = [] -%}
{%- set ext_cols = [] -%}
{%- for col_name, col in all_columns.items() -%}
    {#- Check if column has the configured passthrough prefix -#}
    {%- if col_name.startswith(passthrough_prefix) -%}
        {%- do ext_cols.append(col) -%}
    {%- else -%}
        {%- do core_cols.append(col) -%}
    {%- endif -%}
{%- endfor -%}
{%- set sorted_columns = core_cols + ext_cols -%}

{%- for relation in relations -%}
    {%- set relation_cols = adapter.get_columns_in_relation(relation) | map(attribute='name') | map('lower') | list -%}

    select
    {%- if source_index %}
        {{ loop.index }} as {{ source_index }},
    {%- endif %}
    {%- for col in sorted_columns %}
        {%- if col.name.lower() in relation_cols %}
        {{ col.name }}
        {%- else %}
        cast(null as {{ col.data_type }}) as {{ col.name }}
        {%- endif %}
        {%- if not loop.last %},{% endif %}
    {%- endfor %}
    from {{ relation }}

    {%- if not loop.last %}
    union all
    {% endif -%}
{%- endfor -%}

{% endmacro %}

macro.the_tuva_project.select_extension_.macro_sql:
{% macro select_extension_columns(relation, alias=none, prefix=none, strip_prefix=none) %}
{#
    Selects extension columns from a relation.

    Extension columns are identified by a prefix (default: 'x_').
    This macro reads column metadata directly from the provided relation
    and outputs the extension columns, optionally stripping the prefix.

    Arguments:
        relation: The relation to read extension columns from (typically input_layer__*)
        alias: Optional table alias for column references
        prefix: Column prefix to identify extensions (default: passthrough.prefix var)
        strip_prefix: Whether to strip prefix (default: passthrough.strip var)

    Configuration in dbt_project.yml:
        vars:
          passthrough:
            prefix: 'x_'    # Prefix to identify passthrough columns
            strip: false    # Whether to strip prefix in final output
#}
    {%- if not execute -%}
        {{ return('') }}
    {%- endif -%}

    {%- set passthrough_config = var('passthrough', {}) -%}
    {%- set effective_prefix = prefix if prefix is not none else passthrough_config.get('prefix', 'x_') -%}
    {%- set effective_strip_prefix = strip_prefix if strip_prefix is not none else passthrough_config.get('strip', false) -%}

    {#- Get columns from the relation -#}
    {%- set source_columns = adapter.get_columns_in_relation(relation) -%}

    {%- if source_columns | length == 0 -%}
        {{ return('') }}
    {%- endif -%}

    {%- set alias_prefix = alias ~ '.' if alias else '' -%}
    {%- set extension_columns = [] -%}

    {#- Find extension columns -#}
    {%- for col in source_columns -%}
        {%- if col.name.lower().startswith(effective_prefix.lower()) -%}
            {%- set stripped_name = col.name[effective_prefix | length:] -%}
            {%- if effective_strip_prefix -%}
                {%- set col_expr = alias_prefix ~ col.name ~ ' as ' ~ stripped_name -%}
            {%- else -%}
                {%- set col_expr = alias_prefix ~ col.name -%}
            {%- endif -%}
            {%- do extension_columns.append(col_expr) -%}
        {%- endif -%}
    {%- endfor -%}

    {%- if extension_columns | length > 0 -%}
        {%- for col_expr in extension_columns %}
    , {{ col_expr }}
        {%- endfor -%}
    {%- endif -%}
{% endmacro %}

