          {% if artifacts_hashes is not none %}
            {% do upload_artifacts_func(should_commit=true, metadata_hashes=artifacts_hashes.get(artifacts_model, [])) %}
          {% else %}
            {% do upload_artifacts_func(should_commit=true) %}
