model.the_tuva_project.benchmarks__predi.raw_code:
{{
    config(
        enabled = var('benchmarks_already_created', false) | as_bool
    )
}}

{# Get columns from the non-prospective monthly table to mirror naming #}
{%- set columns = adapter.get_columns_in_relation(ref('benchmarks__predict_member_month')) -%}

{%- set actual_cols = [] -%}
{%- for col in columns -%}
  {%- set n = col.name | lower -%}
  {%- if n.startswith('actual_') -%}
    {%- do actual_cols.append(col.name) -%}
  {%- endif -%}
{%- endfor -%}

{# Build dynamic expected pairs directly from the predictions relation columns #}
{%- set pred_str = var('predictions_person_year_prospective') -%}
{%- set clean = pred_str | replace('`','') | replace('[','') | replace(']','') | replace('"','') -%}
{%- set parts = clean.split('.') -%}
{%- if parts | length == 3 -%}
  {%- set pred_rel = adapter.get_relation(database=parts[0], schema=parts[1], identifier=parts[2]) -%}
{%- elif parts | length == 2 -%}
  {%- set pred_rel = adapter.get_relation(database=target.database, schema=parts[0], identifier=parts[1]) -%}
{%- else -%}
  {%- set pred_rel = none -%}
{%- endif -%}

{%- set pred_cols = adapter.get_columns_in_relation(pred_rel) if pred_rel else [] -%}
{%- set paid_pairs = [] -%}  {# list of [base, output_alias] #}
{%- set count_pairs = [] -%} {# list of [base, output_alias] #}

{%- for col in pred_cols -%}
  {%- set n = col.name | lower -%}
  {%- if n.startswith('pred_pmpm_') -%}
    {%- set base = n | replace('pred_pmpm_','') -%}
    {%- set out_alias = 'expected_paid_amount' if base == 'overall' else 'expected_' ~ base ~ '_paid_amount' -%}
    {%- do paid_pairs.append([base, out_alias]) -%}
  {%- elif n.startswith('pred_pmpc_') -%}
    {%- set base = n | replace('pred_pmpc_','') -%}
    {%- set out_alias = 'expected_' ~ base ~ '_encounter_count' -%}
    {%- do count_pairs.append([base, out_alias]) -%}
  {%- endif -%}
{%- endfor -%}

select
   mm.benchmark_key
 , mm.first_day_of_month
 , mm.year_month
 , mm.person_id
 , mm.payer
 , mm.{{ quote_column('plan') }}
 , mm.data_source
 , cast(left(mm.year_month, 4) as {{ dbt.type_int() }}) as prediction_year

 {# Bring through all actual_* columns dynamically from mm #}
{% for col in actual_cols %}
 , mm.{{ col }}
{% endfor %}

 {# Expected paid amounts from prospective predictions (PMPM), groups + types #}
{% for base, out_col in paid_pairs %}
 , pred.pred_pmpm_{{ base }} as {{ out_col }}
{% endfor %}

 {# Expected encounter counts from prospective predictions (PMPC), groups + types #}
{% for base, out_col in count_pairs %}
 , pred.pred_pmpc_{{ base }} as {{ out_col }}
{% endfor %}

from {{ ref('benchmarks__predict_member_month') }} as mm
inner join {{ var('predictions_person_year_prospective') }} as pred
  on pred.benchmark_key = mm.benchmark_key

model.the_tuva_project.benchmarks__inpat.raw_code:
{{
    config(
        enabled = var('benchmarks_train', False) | as_bool
    )
}}

/*
  Prospective inpatient input:
  - Prediction-year encounter context at encounter grain (same as non-prospective input)
  - Lagged feature flags joined directly from person-year pivot tables with year_nbr - 1
*/

{# --- Build dynamic lists of lag feature columns from pivot tables --- #}
{% set rel_pc   = ref('benchmarks__pivot_condition') %}
{% set rel_pcms = ref('benchmarks__pivot_cms_condition') %}
{% set rel_phcc = ref('benchmarks__pivot_hcc') %}

{% set pc_cols   = adapter.get_columns_in_relation(rel_pc) %}
{% set pcms_cols = adapter.get_columns_in_relation(rel_pcms) %}
{% set phcc_cols = adapter.get_columns_in_relation(rel_phcc) %}

{% set excluded_pc_cols = ['person_id','year_nbr','payer','plan','data_source','benchmark_key','tuva_last_run'] %}

{% set cond_cols = [] %}
{% for c in pc_cols %}
  {% set n = c.name | lower %}
  {% if n not in excluded_pc_cols %}
    {% do cond_cols.append(n) %}
  {% endif %}
{% endfor %}

{% set cms_cols = [] %}
{% for c in pcms_cols %}
  {% set n = c.name | lower %}
  {% if n.startswith('cms_') %}
    {% do cms_cols.append(n) %}
  {% endif %}
{% endfor %}

{% set hcc_cols = [] %}
{% for c in phcc_cols %}
  {% set n = c.name | lower %}
  {% if n.startswith('hcc_') %}
    {% do hcc_cols.append(n) %}
  {% endif %}
{% endfor %}

with base as (
  select
      ii.encounter_id
    , ce.person_id
    , ii.data_source
    , ii.year_nbr as prediction_year
    , ii.year_nbr - 1 as diagnosis_year
    , ii.sex as prediction_year_sex
    , ii.race as prediction_year_race
    , ii.state as prediction_year_state
    , ii.age_at_admit as prediction_year_age_at_admit
    , ii.length_of_stay
    , ii.discharge_location
    , ii.ms_drg_code
    , ii.ccsr_cat
    , ii.readmission_numerator
    , ii.readmission_denominator
  from {{ ref('benchmarks__inpatient_input') }} as ii
  inner join {{ ref('benchmarks__stg_core__encounter') }} as ce
    on ii.encounter_id = ce.encounter_id
)

select
    b.encounter_id
  , b.person_id
  , b.data_source
  , b.prediction_year
  , b.diagnosis_year
  , b.prediction_year_sex
  , b.prediction_year_race
  , b.prediction_year_state
  , b.prediction_year_age_at_admit
  , b.length_of_stay
  , b.discharge_location
  , b.ms_drg_code
  , b.ccsr_cat
  , b.readmission_numerator
  , b.readmission_denominator

  -- lag presence flags (based on availability of any prior-year pivot rows)
  , case when pc.person_id is null or pcms.person_id is null or phcc.person_id is null then 1 else 0 end as lag_missing
  , case when pc.person_id is null and pcms.person_id is null and phcc.person_id is null then 1 else 0 end as cold_start

  {# --- lagged Tuva chronic conditions (prior year) --- #}
{% for col in cond_cols %}
  , coalesce(pc.{{ col }}, 0) as lag_cond_{{ col }}
{% endfor %}

  {# --- lagged CMS condition flags (prior year) --- #}
{% for col in cms_cols %}
  , coalesce(pcms.{{ col }}, 0) as lag_{{ col }}
{% endfor %}

  {# --- lagged HCC flags (prior year) --- #}
{% for col in hcc_cols %}
  , coalesce(phcc.{{ col }}, 0) as lag_{{ col }}
{% endfor %}

  -- run metadata stamp
  , cast('{{ var('tuva_last_run') }}' as {{ dbt.type_timestamp() }}) as tuva_last_run

